<template>
  <div
    :class="
      cn(
        'peer h-5 w-5 shrink-0 rounded-sm border border-primary ring-offset-background focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 disabled:cursor-not-allowed disabled:opacity-50 data-[state=checked]:bg-primary data-[state=checked]:text-primary-foreground',
        props.class
      )
    "
    @click="onUpdate"
  >
    <input :id="id" type="checkbox" hidden="hidden" />
    <div class="flex h-full w-full items-center justify-center text-current">
      <Check v-if="model === true" class="h-5 w-5 text-green-600" />
      <XIcon v-else-if="model === false" class="h-5 w-5 text-red-600" />
    </div>
  </div>
</template>
<script setup lang="ts">
import type { CheckboxRootProps } from 'reka-ui';
import { cn } from '@/components/ui/utils';
import { computed, type HTMLAttributes } from 'vue';

const props = defineProps<CheckboxRootProps & { class?: HTMLAttributes['class'] }>();
const delegatedProps = computed(() => {
  const { class: _, ...delegated } = props;

  return delegated;
});

import { Check, XIcon } from 'lucide-vue-next';

const model = defineModel<boolean | 'indeterminate'>({ required: true });

function onUpdate() {
  if (model.value === true) {
    model.value = false;
  } else if (model.value === false) {
    model.value = 'indeterminate';
  } else if (model.value === 'indeterminate') {
    model.value = true;
  }
}
</script>
